from google.cloud import speech_v1 as speech

def timestamped_transcript(operation_name: str):
    client = speech.SpeechClient()
    operation = client.get_operation(name=operation_name)
    if operation.done:
        response = client.operations_v1.Operation.response(operation)
        for result in response.results:
            for alternative in result.alternatives:
                for word_info in alternative.words:
                    print(f'Word: {word_info.word}, Start Time: {word_info.start_time}, End Time: {word_info.end_time}')
    else:
        print('Transcription is still in progress.')

from google.cloud import speech_v1 as speech

def create_speech_client():
    return speech.SpeechClient()

def build_recognition_config(encoding, sample_rate_hertz, language_code, enable_speaker_diarization=False, diarization_speaker_count=None):
    config = speech.types.RecognitionConfig(
        encoding=encoding,
        sample_rate_hertz=sample_rate_hertz,
        language_code=language_code,
    )
    if enable_speaker_diarization:
        config.enable_speaker_diarization = True
        if diarization_speaker_count:
            config.diarization_speaker_count = diarization_speaker_count
    return config

from google.cloud.speech_v1 import enums

def normalize_transcript(transcript):
    return transcript.lower()

def extract_word_timestamps(response):
    word_timestamps = []
    for result in response.results:
        for alternative in result.alternatives:
            for word_info in alternative.words:
                word_timestamps.append((word_info.word, word_info.start_time, word_info.end_time))
    return word_timestamps
